AddItemAt.src:
function (index_, text_)
	{
		if (this.runtime.isDomFree)
			return;
		index_ = Math.floor(index_);
		if (index_ < 0)
			index_ = 0;
		var o = document.createElement("option");
		o.text = text_;
		if (index_ >= this.elem.length)
			this.elem.add(o);
		else
		{
			this.elem.add(o, this.elem.options[index_]);
		}
	}

Remove.src:
